const pairs: DiffPair[] = [
  // ── Physics ──
  { slug: 'difference-between-speed-and-velocity', term1: 'Speed', term2: 'Velocity', exam: 'Both', subject: 'Physics', chapter: 'Kinematics', intro: 'Speed and velocity are fundamental concepts in kinematics. While often used interchangeably in everyday language, they have distinct scientific definitions. Speed is a scalar quantity measuring how fast an object moves, while velocity is a vector quantity that includes both speed and direction.', rows: [['Definition', 'Rate of change of distance', 'Rate of change of displacement'], ['Type', 'Scalar quantity', 'Vector quantity'], ['Direction', 'No direction', 'Has direction'], ['Formula', 'Speed = Distance / Time', 'Velocity = Displacement / Time'], ['Value', 'Always positive or zero', 'Can be positive, negative, or zero'], ['SI Unit', 'm/s', 'm/s'], ['Average', 'Total distance / Total time', 'Total displacement / Total time'], ['Example', 'Car travels at 60 km/h', 'Car travels at 60 km/h North']], keyPoints: ['Speed can never be negative; velocity can be negative (opposite direction)', 'For circular motion, average velocity is zero but average speed is non-zero', 'Instantaneous speed equals magnitude of instantaneous velocity', 'Speed ≥ |Velocity| always holds true'], faqs: [{ q: 'Can speed be greater than velocity?', a: 'Yes, for any non-straight path, the total distance covered is greater than displacement, making average speed greater than the magnitude of average velocity.' }, { q: 'Is velocity more important than speed for JEE/NEET?', a: 'Yes, velocity is used far more in physics problems because direction matters in force, momentum, and energy calculations.' }], relatedSlugs: ['difference-between-distance-and-displacement', 'jee-physics-mechanics'] },

  { slug: 'difference-between-distance-and-displacement', term1: 'Distance', term2: 'Displacement', exam: 'Both', subject: 'Physics', chapter: 'Kinematics', intro: 'Distance and displacement are two ways to measure how far an object has moved. Distance measures the total path length traveled, while displacement measures the shortest straight-line distance between start and end points.', rows: [['Definition', 'Total path length traveled', 'Shortest distance between initial and final position'], ['Type', 'Scalar', 'Vector'], ['Value', 'Always ≥ 0', 'Can be positive, negative, or zero'], ['Path Dependent', 'Yes', 'No'], ['SI Unit', 'Meter (m)', 'Meter (m)'], ['For circular trip', 'Equal to circumference', 'Zero']], keyPoints: ['Distance ≥ |Displacement| for any path', 'For straight-line motion in one direction, Distance = |Displacement|', 'Displacement depends only on initial and final positions', 'Distance is always non-negative'], faqs: [{ q: 'When are distance and displacement equal?', a: 'They are equal only when the object moves in a straight line without changing direction.' }], relatedSlugs: ['difference-between-speed-and-velocity', 'jee-physics-mechanics'] },

  { slug: 'difference-between-mass-and-weight', term1: 'Mass', term2: 'Weight', exam: 'Both', subject: 'Physics', chapter: 'Laws of Motion', intro: 'Mass and weight are commonly confused but are fundamentally different physical quantities. Mass is the amount of matter in an object, while weight is the gravitational force acting on that mass.', rows: [['Definition', 'Amount of matter in object', 'Force of gravity on object'], ['Type', 'Scalar', 'Vector (directed toward center of gravity)'], ['SI Unit', 'Kilogram (kg)', 'Newton (N)'], ['Formula', 'Constant', 'W = mg'], ['Varies with location?', 'No', 'Yes (depends on g)'], ['Zero gravity', 'Remains same', 'Becomes zero'], ['Measured by', 'Beam balance', 'Spring balance']], keyPoints: ['Mass is intrinsic; weight depends on gravitational acceleration', 'Weight on Moon is ~1/6th of weight on Earth', 'In space (zero-g), weight = 0 but mass remains unchanged', 'Mass is measured in kg; weight in Newton (1 kg weight ≈ 9.8 N on Earth)'], faqs: [{ q: 'Is mass or weight used in JEE problems?', a: 'Both. Mass appears in F=ma, momentum, and energy equations. Weight (mg) appears in gravitational force problems, inclined planes, and projectile motion.' }], relatedSlugs: ['difference-between-scalar-and-vector', 'jee-physics-mechanics'] },

  { slug: 'difference-between-scalar-and-vector', term1: 'Scalar', term2: 'Vector', exam: 'Both', subject: 'Physics', intro: 'Scalars and vectors are two types of physical quantities. Scalars have only magnitude, while vectors have both magnitude and direction. This distinction is fundamental to all of physics.', rows: [['Definition', 'Quantity with only magnitude', 'Quantity with magnitude and direction'], ['Examples', 'Mass, Speed, Energy, Temperature', 'Force, Velocity, Displacement, Acceleration'], ['Addition', 'Simple arithmetic addition', 'Triangle law / Parallelogram law'], ['Notation', 'Regular letters (m, T)', 'Arrow notation or bold (F⃗, v)'], ['Components', 'None', 'Can be resolved into components'], ['Negative value', 'Some can be negative (temperature)', 'Direction reverses']], keyPoints: ['Vector addition follows the parallelogram or triangle law, not simple addition', 'Dot product of two vectors gives a scalar; cross product gives a vector', 'Work (scalar) = Force (vector) · Displacement (vector)', 'A vector can be completely described by its components along coordinate axes'], faqs: [{ q: 'Is energy a scalar or vector?', a: 'Energy is a scalar quantity. It has magnitude but no direction. Both kinetic and potential energy are scalars.' }], relatedSlugs: ['difference-between-speed-and-velocity', 'difference-between-distance-and-displacement'] },

  { slug: 'difference-between-work-and-energy', term1: 'Work', term2: 'Energy', exam: 'Both', subject: 'Physics', chapter: 'Work, Energy and Power', intro: 'Work and energy are closely related concepts in physics. Work is the transfer of energy when a force moves an object, while energy is the capacity to do work.', rows: [['Definition', 'Force × displacement × cos θ', 'Capacity to do work'], ['SI Unit', 'Joule (J)', 'Joule (J)'], ['Type', 'Scalar', 'Scalar'], ['Can be negative?', 'Yes (when force opposes motion)', 'Kinetic energy: No. Potential energy: Yes'], ['Forms', 'Only one form', 'Multiple forms (KE, PE, thermal, etc.)'], ['Transfer', 'Mechanism of energy transfer', 'What gets transferred']], keyPoints: ['Work-Energy Theorem: Net work = Change in kinetic energy', 'Work done by conservative forces = -ΔPE', 'Energy is conserved in isolated systems; work is not a conserved quantity', 'Power = Rate of doing work = Rate of energy transfer'], faqs: [{ q: 'Can work be negative?', a: 'Yes. When the force component is opposite to displacement (θ > 90°), work is negative. Example: friction always does negative work on a moving object.' }], relatedSlugs: ['difference-between-kinetic-and-potential-energy', 'jee-physics-mechanics'] },

  { slug: 'difference-between-kinetic-and-potential-energy', term1: 'Kinetic Energy', term2: 'Potential Energy', exam: 'Both', subject: 'Physics', intro: 'Kinetic energy is the energy of motion, while potential energy is stored energy due to position or configuration. Together, they form mechanical energy.', rows: [['Definition', 'Energy due to motion', 'Energy due to position/configuration'], ['Formula', 'KE = ½mv²', 'PE = mgh (gravitational)'], ['Depends on', 'Mass and velocity', 'Mass, height, or configuration'], ['Zero when', 'Object is at rest', 'At reference level'], ['Always positive?', 'Yes', 'No (can be negative)'], ['Transfer', 'Decreases when object decelerates', 'Converts to KE when released']], keyPoints: ['In free fall, PE converts to KE (total energy conserved)', 'At the highest point of a projectile, KE is minimum and PE is maximum', 'Spring PE = ½kx² (elastic potential energy)', 'Total mechanical energy = KE + PE = constant (in absence of non-conservative forces)'], faqs: [{ q: 'Can kinetic energy be negative?', a: 'No, kinetic energy (½mv²) is always non-negative since mass is positive and v² is always positive.' }], relatedSlugs: ['difference-between-work-and-energy', 'jee-physics-mechanics'] },

  { slug: 'difference-between-ac-and-dc', term1: 'AC (Alternating Current)', term2: 'DC (Direct Current)', exam: 'Both', subject: 'Physics', chapter: 'Current Electricity', intro: 'AC and DC are two types of electrical current. AC periodically reverses direction, while DC flows in one direction. Most household electricity is AC, while batteries provide DC.', rows: [['Direction', 'Reverses periodically', 'Flows in one direction'], ['Source', 'AC generators, power grid', 'Batteries, solar cells, DC generators'], ['Waveform', 'Sinusoidal', 'Straight line'], ['Frequency', '50 Hz (India) / 60 Hz (US)', '0 Hz (zero frequency)'], ['Transmission', 'Efficient over long distances', 'Loses energy over long distances'], ['Transformer', 'Can step up/down voltage', 'Cannot use transformers directly'], ['Danger', 'More dangerous at same voltage', 'Relatively safer']], keyPoints: ['AC can be transmitted over long distances with minimal loss using transformers', 'RMS value of AC = Peak value / √2', 'Power in AC circuits: P = Vrms × Irms × cos φ', 'Most electronic devices internally convert AC to DC using rectifiers'], faqs: [{ q: 'Why is AC used for power transmission?', a: 'AC voltage can be easily stepped up using transformers for long-distance transmission (reducing I²R losses) and stepped down for safe household use.' }], relatedSlugs: ['jee-physics-electrodynamics'] },

  // ── Chemistry ──
  { slug: 'difference-between-atom-and-molecule', term1: 'Atom', term2: 'Molecule', exam: 'Both', subject: 'Chemistry', intro: 'Atoms are the smallest unit of an element, while molecules are formed when two or more atoms bond together. Understanding this distinction is fundamental to chemistry.', rows: [['Definition', 'Smallest unit of an element', 'Two or more atoms bonded together'], ['Existence', 'May or may not exist independently', 'Can exist independently'], ['Composition', 'Protons, neutrons, electrons', 'Two or more atoms'], ['Shape', 'Spherical', 'Various geometric shapes'], ['Example', 'H, O, Na, Fe', 'H₂, O₂, H₂O, CO₂'], ['Reactivity', 'May be reactive', 'Can be stable or reactive'], ['Visibility', 'Not visible even under microscope', 'Not visible (some large ones visible via electron microscope)']], keyPoints: ['Noble gases exist as single atoms (monoatomic molecules)', 'Homonuclear molecules: same atoms (O₂, N₂)', 'Heteronuclear molecules: different atoms (H₂O, CO₂)', 'Molecular mass = sum of atomic masses of constituent atoms'], faqs: [{ q: 'Can an atom exist independently?', a: 'Most atoms cannot exist independently and tend to form molecules or ionic compounds. Noble gases (He, Ne, Ar) are exceptions that exist as single atoms.' }], relatedSlugs: ['difference-between-element-and-compound', 'difference-between-ionic-and-covalent-bond'] },

  { slug: 'difference-between-element-and-compound', term1: 'Element', term2: 'Compound', exam: 'Both', subject: 'Chemistry', intro: 'Elements are pure substances made of one type of atom, while compounds are substances made of two or more elements chemically bonded in fixed ratios.', rows: [['Definition', 'Pure substance with one type of atom', 'Substance with two or more elements in fixed ratio'], ['Composition', 'Single type of atom', 'Multiple types of atoms'], ['Total known', '118 elements', 'Millions of compounds'], ['Separation', 'Cannot be broken down chemically', 'Can be broken into elements'], ['Properties', 'Properties of constituent atoms', 'Properties differ from constituent elements'], ['Example', 'Gold (Au), Oxygen (O₂)', 'Water (H₂O), Salt (NaCl)']], keyPoints: ['Elements are organized in the Periodic Table', 'Compounds have fixed composition by mass (Law of Definite Proportions)', 'Mixtures ≠ Compounds (mixtures have variable composition)', 'Compounds can only be separated by chemical reactions'], faqs: [{ q: 'Is water an element or compound?', a: 'Water (H₂O) is a compound made of hydrogen and oxygen in a 2:1 ratio by number of atoms.' }], relatedSlugs: ['difference-between-atom-and-molecule', 'difference-between-mixture-and-compound'] },

  { slug: 'difference-between-ionic-and-covalent-bond', term1: 'Ionic Bond', term2: 'Covalent Bond', exam: 'Both', subject: 'Chemistry', chapter: 'Chemical Bonding', intro: 'Ionic and covalent bonds are the two primary types of chemical bonds. Ionic bonds involve transfer of electrons, while covalent bonds involve sharing of electrons.', rows: [['Formation', 'Transfer of electrons', 'Sharing of electrons'], ['Between', 'Metal + Non-metal', 'Non-metal + Non-metal'], ['Electronegativity diff', 'Large (>1.7)', 'Small (<1.7)'], ['State at room temp', 'Usually solid', 'Solid, liquid, or gas'], ['Melting point', 'High', 'Low to moderate'], ['Conductivity', 'Conducts in solution/molten', 'Poor conductor'], ['Solubility', 'Soluble in water (polar)', 'Soluble in organic solvents'], ['Example', 'NaCl, KBr, MgO', 'H₂O, CH₄, CO₂']], keyPoints: ['Ionic bonds form crystal lattice structures with high lattice energy', 'Covalent bonds can be single (σ), double (σ+π), or triple (σ+2π)', 'Polar covalent bonds exist when sharing is unequal (e.g., H-Cl)', 'Bond polarity increases with electronegativity difference'], faqs: [{ q: 'Can a bond be both ionic and covalent?', a: 'Bonds exist on a spectrum. Polar covalent bonds have some ionic character. Fajan\'s rules describe when ionic compounds show covalent character.' }], relatedSlugs: ['difference-between-sigma-and-pi-bond', 'jee-chemistry-inorganic'] },

  { slug: 'difference-between-sigma-and-pi-bond', term1: 'Sigma (σ) Bond', term2: 'Pi (π) Bond', exam: 'JEE', subject: 'Chemistry', chapter: 'Chemical Bonding', intro: 'Sigma and pi bonds are the two types of covalent bonds formed by orbital overlap. Understanding their differences is crucial for organic chemistry and molecular geometry.', rows: [['Overlap', 'Head-on (axial) overlap', 'Lateral (sideways) overlap'], ['Strength', 'Stronger', 'Weaker'], ['Rotation', 'Free rotation possible', 'Restricts rotation'], ['Formation', 's-s, s-p, p-p head-on', 'p-p lateral overlap'], ['Number per bond', 'Always first bond formed', 'Second and third bonds'], ['Shape', 'Cylindrically symmetric', 'Two lobes above and below'], ['Example', 'Single bond in H₂', 'Second bond in O₂ (O=O)']], keyPoints: ['A single bond = 1σ; double bond = 1σ + 1π; triple bond = 1σ + 2π', 'σ bonds determine molecular geometry (VSEPR theory)', 'π bonds are responsible for resonance and conjugation', 'Hybridization affects σ bonds (sp, sp², sp³)'], faqs: [{ q: 'Why is a sigma bond stronger than a pi bond?', a: 'Sigma bonds have head-on orbital overlap with maximum overlap density along the bond axis, resulting in greater bond strength than the lateral overlap in pi bonds.' }], relatedSlugs: ['difference-between-ionic-and-covalent-bond'] },

  { slug: 'difference-between-oxidation-and-reduction', term1: 'Oxidation', term2: 'Reduction', exam: 'Both', subject: 'Chemistry', chapter: 'Redox Reactions', intro: 'Oxidation and reduction are complementary chemical processes that always occur together (redox reactions). Oxidation involves loss of electrons, while reduction involves gain of electrons.', rows: [['Definition', 'Loss of electrons', 'Gain of electrons'], ['Oxidation number', 'Increases', 'Decreases'], ['Oxygen', 'Gain of oxygen', 'Loss of oxygen'], ['Hydrogen', 'Loss of hydrogen', 'Gain of hydrogen'], ['Agent', 'Reducing agent gets oxidized', 'Oxidizing agent gets reduced'], ['Example', 'Na → Na⁺ + e⁻', 'Cl₂ + 2e⁻ → 2Cl⁻'], ['Mnemonic', 'OIL (Oxidation Is Loss)', 'RIG (Reduction Is Gain)']], keyPoints: ['Remember: OIL RIG — Oxidation Is Loss, Reduction Is Gain', 'In electrochemical cells: oxidation at anode, reduction at cathode', 'Oxidizing agents accept electrons (get reduced themselves)', 'Common oxidizing agents: KMnO₄, K₂Cr₂O₇, HNO₃, O₂'], faqs: [{ q: 'Can a substance be both oxidized and reduced?', a: 'Yes, in disproportionation reactions. For example, H₂O₂ can act as both oxidizing and reducing agent: 2H₂O₂ → 2H₂O + O₂.' }], relatedSlugs: ['jee-chemistry-physical'] },

  { slug: 'difference-between-acid-and-base', term1: 'Acid', term2: 'Base', exam: 'Both', subject: 'Chemistry', intro: 'Acids and bases are two fundamental classes of chemical compounds. Acids donate protons (H⁺), while bases accept protons. Their reactions are central to chemistry.', rows: [['Arrhenius', 'Produces H⁺ in water', 'Produces OH⁻ in water'], ['Brønsted-Lowry', 'Proton (H⁺) donor', 'Proton (H⁺) acceptor'], ['Lewis', 'Electron pair acceptor', 'Electron pair donor'], ['pH', '< 7', '> 7'], ['Taste', 'Sour', 'Bitter'], ['Litmus', 'Turns blue → red', 'Turns red → blue'], ['Example', 'HCl, H₂SO₄, CH₃COOH', 'NaOH, KOH, NH₃']], keyPoints: ['pH scale: 0 (strongly acidic) → 7 (neutral) → 14 (strongly basic)', 'Acid + Base → Salt + Water (neutralization)', 'Buffer solutions resist pH changes (weak acid + conjugate base)', 'Ka × Kb = Kw = 10⁻¹⁴ at 25°C'], faqs: [{ q: 'What is the difference between strong and weak acids?', a: 'Strong acids (HCl, H₂SO₄) completely dissociate in water. Weak acids (CH₃COOH, H₂CO₃) only partially dissociate, establishing an equilibrium.' }], relatedSlugs: ['difference-between-oxidation-and-reduction'] },

  { slug: 'difference-between-mixture-and-compound', term1: 'Mixture', term2: 'Compound', exam: 'Both', subject: 'Chemistry', intro: 'Mixtures and compounds are fundamentally different. Mixtures are physical combinations of substances, while compounds are chemical combinations with fixed ratios and new properties.', rows: [['Composition', 'Variable proportions', 'Fixed proportions (by mass)'], ['Separation', 'Physical methods (filtration, distillation)', 'Chemical reactions only'], ['Properties', 'Retain individual properties', 'New properties emerge'], ['Energy', 'No energy change on mixing', 'Energy released or absorbed on formation'], ['Formula', 'No chemical formula', 'Has a definite chemical formula'], ['Example', 'Air, salt water, alloys', 'H₂O, NaCl, CO₂']], keyPoints: ['Mixtures can be homogeneous (solutions) or heterogeneous (suspensions)', 'Compounds follow the Law of Definite Proportions', 'Alloys are homogeneous mixtures of metals', 'Solutions are homogeneous mixtures with uniform composition'], faqs: [{ q: 'Is air a mixture or compound?', a: 'Air is a homogeneous mixture of gases: ~78% N₂, ~21% O₂, ~1% Ar, and trace amounts of CO₂, water vapor, etc.' }], relatedSlugs: ['difference-between-element-and-compound', 'difference-between-atom-and-molecule'] },

  { slug: 'difference-between-exothermic-and-endothermic', term1: 'Exothermic Reaction', term2: 'Endothermic Reaction', exam: 'Both', subject: 'Chemistry', chapter: 'Thermodynamics', intro: 'Chemical reactions either release or absorb energy. Exothermic reactions release heat to surroundings, while endothermic reactions absorb heat from surroundings.', rows: [['Heat', 'Released to surroundings', 'Absorbed from surroundings'], ['ΔH', 'Negative (ΔH < 0)', 'Positive (ΔH > 0)'], ['Temperature', 'Surroundings get warmer', 'Surroundings get cooler'], ['Energy level', 'Products lower than reactants', 'Products higher than reactants'], ['Bond energy', 'Bond formation > Bond breaking', 'Bond breaking > Bond formation'], ['Example', 'Combustion, neutralization', 'Photosynthesis, melting ice']], keyPoints: ['Exothermic: combustion of fuels, acid-base neutralization, crystallization', 'Endothermic: thermal decomposition, photosynthesis, evaporation', 'ΔG = ΔH - TΔS determines spontaneity, not ΔH alone', 'Hess\'s Law: ΔH is independent of the path of the reaction'], faqs: [{ q: 'Is dissolving salt in water exothermic or endothermic?', a: 'Dissolving NaCl in water is slightly endothermic (the solution cools slightly). However, dissolving NaOH is highly exothermic.' }], relatedSlugs: ['jee-chemistry-physical'] },

  // ── Biology (NEET) ──
  { slug: 'difference-between-mitosis-and-meiosis', term1: 'Mitosis', term2: 'Meiosis', exam: 'NEET', subject: 'Biology', chapter: 'Cell Division', intro: 'Mitosis and meiosis are the two types of cell division. Mitosis produces identical daughter cells for growth and repair, while meiosis produces genetically diverse gametes for sexual reproduction.', rows: [['Purpose', 'Growth and repair', 'Gamete formation'], ['Daughter cells', '2 identical cells', '4 genetically different cells'], ['Chromosome number', 'Maintained (2n → 2n)', 'Halved (2n → n)'], ['Divisions', 'One division', 'Two divisions (Meiosis I + II)'], ['Crossing over', 'Rare', 'Occurs in Prophase I'], ['Genetic variation', 'No variation', 'High variation'], ['Where', 'Somatic cells', 'Reproductive cells'], ['Stages', 'Prophase, Metaphase, Anaphase, Telophase', 'Same stages but twice (I and II)']], keyPoints: ['Meiosis I is reductional (2n→n); Meiosis II is equational (n→n)', 'Crossing over in Prophase I creates genetic diversity', 'Mitosis maintains chromosome number; meiosis halves it', 'Non-disjunction in meiosis leads to chromosomal disorders (Down syndrome)'], faqs: [{ q: 'Why is meiosis important for evolution?', a: 'Meiosis creates genetic variation through crossing over and independent assortment, providing raw material for natural selection and evolution.' }], relatedSlugs: ['difference-between-dna-and-rna', 'neet-biology-coaching'] },

  { slug: 'difference-between-dna-and-rna', term1: 'DNA', term2: 'RNA', exam: 'NEET', subject: 'Biology', chapter: 'Molecular Basis of Inheritance', intro: 'DNA and RNA are the two types of nucleic acids essential for life. DNA stores genetic information, while RNA helps in protein synthesis.', rows: [['Full form', 'Deoxyribonucleic Acid', 'Ribonucleic Acid'], ['Sugar', 'Deoxyribose', 'Ribose'], ['Bases', 'A, T, G, C', 'A, U, G, C'], ['Structure', 'Double-stranded helix', 'Usually single-stranded'], ['Location', 'Nucleus (mainly)', 'Nucleus and cytoplasm'], ['Function', 'Stores genetic information', 'Protein synthesis, gene regulation'], ['Stability', 'More stable', 'Less stable'], ['Types', 'Only one type', 'mRNA, tRNA, rRNA, snRNA']], keyPoints: ['DNA replication is semi-conservative (Meselson-Stahl experiment)', 'Central Dogma: DNA → RNA (transcription) → Protein (translation)', 'RNA can act as enzyme (ribozymes)', 'DNA has thymine; RNA has uracil instead'], faqs: [{ q: 'Can RNA store genetic information?', a: 'Yes, some viruses (like HIV, SARS-CoV-2) use RNA as their genetic material instead of DNA.' }], relatedSlugs: ['difference-between-mitosis-and-meiosis'] },

  { slug: 'difference-between-photosynthesis-and-respiration', term1: 'Photosynthesis', term2: 'Cellular Respiration', exam: 'NEET', subject: 'Biology', intro: 'Photosynthesis and cellular respiration are complementary metabolic processes. Photosynthesis converts light energy to chemical energy, while respiration releases stored chemical energy.', rows: [['Process', 'Builds glucose (anabolic)', 'Breaks down glucose (catabolic)'], ['Equation', '6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂', 'C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O'], ['Energy', 'Absorbs light energy', 'Releases chemical energy (ATP)'], ['Location', 'Chloroplasts', 'Mitochondria'], ['Occurs in', 'Plants, algae, some bacteria', 'All living organisms'], ['Requirement', 'Light, CO₂, H₂O', 'Glucose, O₂ (aerobic)'], ['Products', 'Glucose, O₂', 'CO₂, H₂O, ATP']], keyPoints: ['Photosynthesis occurs in two stages: Light reactions and Calvin cycle', 'Respiration occurs in three stages: Glycolysis, Krebs cycle, ETC', 'Net ATP from one glucose molecule: ~36-38 ATP', 'Both processes involve electron transport chains'], faqs: [{ q: 'Do plants do both photosynthesis and respiration?', a: 'Yes, plants perform photosynthesis during the day and cellular respiration 24/7. During the day, photosynthesis rate exceeds respiration rate.' }], relatedSlugs: ['neet-biology-coaching'] },

  { slug: 'difference-between-arteries-and-veins', term1: 'Arteries', term2: 'Veins', exam: 'NEET', subject: 'Biology', chapter: 'Body Fluids and Circulation', intro: 'Arteries and veins are blood vessels with different structures and functions. Arteries carry blood away from the heart, while veins return blood to the heart.', rows: [['Direction', 'Away from heart', 'Toward heart'], ['Blood type', 'Usually oxygenated (except pulmonary artery)', 'Usually deoxygenated (except pulmonary vein)'], ['Wall thickness', 'Thick, muscular walls', 'Thin walls'], ['Lumen', 'Narrow', 'Wide'], ['Valves', 'No valves (except aortic/pulmonary)', 'Have valves to prevent backflow'], ['Pressure', 'High pressure', 'Low pressure'], ['Pulse', 'Pulse felt', 'No pulse'], ['Location', 'Deep in body', 'Superficial and deep']], keyPoints: ['Pulmonary artery carries deoxygenated blood (exception)', 'Pulmonary vein carries oxygenated blood (exception)', 'Arterioles regulate blood pressure through vasoconstriction/vasodilation', 'Veins have a larger total cross-sectional area than arteries'], faqs: [{ q: 'Why do arteries have thicker walls?', a: 'Arteries carry blood at high pressure from the heart, so they need thick, elastic, muscular walls to withstand and maintain this pressure.' }], relatedSlugs: ['neet-biology-coaching'] },

  // ── Exam Comparisons ──
  { slug: 'difference-between-jee-main-and-advanced', term1: 'JEE Main', term2: 'JEE Advanced', exam: 'JEE', subject: 'Exam', intro: 'JEE Main and JEE Advanced are the two stages of the Joint Entrance Examination for engineering admissions in India. JEE Main is the qualifying exam for JEE Advanced and for admission to NITs, while JEE Advanced is for IIT admission.', rows: [['Purpose', 'Admission to NITs, IIITs, GFTIs', 'Admission to IITs'], ['Conducting body', 'NTA', 'One of the IITs (rotational)'], ['Eligibility', 'Class 12 passed/appearing', 'Top 2.5 lakh JEE Main qualifiers'], ['Attempts', '3 consecutive years', '2 consecutive years'], ['Mode', 'Computer-based (CBT)', 'Computer-based (CBT)'], ['Papers', '1 paper, 3 hours', '2 papers, 3 hours each'], ['Difficulty', 'Moderate', 'High to Very High'], ['Total candidates', '~12-15 lakh', '~1.5-2 lakh']], keyPoints: ['You must qualify JEE Main to be eligible for JEE Advanced', 'JEE Main uses percentile-based ranking; JEE Advanced uses aggregate marks', 'JEE Advanced has unique question types: multi-correct, matrix match, integer', 'Top 250 ranks in JEE Advanced can choose any branch at any IIT'], faqs: [{ q: 'Can I get into IIT through JEE Main?', a: 'No, IIT admission requires qualifying JEE Advanced. JEE Main is for NITs, IIITs, and GFTIs. JEE Main also serves as the qualifying exam for JEE Advanced.' }, { q: 'Is JEE Advanced harder than JEE Main?', a: 'Yes, significantly. JEE Advanced tests deeper conceptual understanding with multi-concept problems and unique question formats not found in JEE Main.' }], relatedSlugs: ['jee-coaching', 'jee-advanced-coaching', 'jee-main-coaching'] },

  { slug: 'difference-between-jee-and-neet', term1: 'JEE', term2: 'NEET', exam: 'Both', subject: 'Exam', intro: 'JEE and NEET are India\'s premier entrance exams for engineering and medical admissions respectively. They differ significantly in syllabus, pattern, and preparation strategy.', rows: [['Purpose', 'Engineering (IIT/NIT/IIIT)', 'Medical (MBBS/BDS/AYUSH)'], ['Subjects', 'Physics, Chemistry, Mathematics', 'Physics, Chemistry, Biology'], ['Conducting body', 'NTA', 'NTA'], ['Mode', 'Computer-based', 'Pen and paper (OMR)'], ['Sessions', '2 per year', '1 per year'], ['Total marks', '300', '720'], ['Difficulty', 'High (especially Maths)', 'Moderate (NCERT-focused)'], ['Attempts', '3 (Main) + 2 (Advanced)', 'Unlimited']], keyPoints: ['JEE tests mathematical problem-solving; NEET tests biological knowledge', 'NCERT is sufficient for 70-80% of NEET but only 30-40% of JEE', 'JEE Advanced is considered India\'s toughest entrance exam', 'A student choosing between JEE and NEET should decide based on interest, not difficulty'], faqs: [{ q: 'Can I prepare for both JEE and NEET simultaneously?', a: 'It\'s extremely difficult because JEE requires Mathematics while NEET requires Biology. Physics and Chemistry overlap, but the depth and approach differ. Focus on one exam for best results.' }], relatedSlugs: ['jee-coaching', 'neet-coaching'] },

  // ── Maths ──
  { slug: 'difference-between-permutation-and-combination', term1: 'Permutation', term2: 'Combination', exam: 'JEE', subject: 'Mathematics', chapter: 'Permutations and Combinations', intro: 'Permutations and combinations are counting techniques. The key difference is that permutations consider order while combinations do not.', rows: [['Order', 'Matters', 'Does not matter'], ['Formula', 'nPr = n!/(n-r)!', 'nCr = n!/[r!(n-r)!]'], ['Meaning', 'Arrangements', 'Selections'], ['Value', 'nPr ≥ nCr', 'nCr ≤ nPr'], ['Example', 'Arranging 3 books on a shelf', 'Choosing 3 books from 5'], ['Relationship', 'nPr = nCr × r!', 'nCr = nPr / r!']], keyPoints: ['Use permutation when "arrangement" or "order" is mentioned', 'Use combination when "selection" or "choose" is mentioned', 'nCr = nC(n-r) — symmetry property', 'Pascal\'s Triangle gives combination values'], faqs: [{ q: 'How to decide between permutation and combination?', a: 'Ask yourself: Does changing the order create a different result? If yes → Permutation. If no → Combination. Example: Lock code (order matters) = Permutation; Committee selection (order doesn\'t matter) = Combination.' }], relatedSlugs: ['jee-math-algebra'] },

  { slug: 'difference-between-arithmetic-and-geometric-progression', term1: 'Arithmetic Progression (AP)', term2: 'Geometric Progression (GP)', exam: 'JEE', subject: 'Mathematics', chapter: 'Sequences and Series', intro: 'AP and GP are fundamental sequences in mathematics. In AP, consecutive terms differ by a constant; in GP, consecutive terms have a constant ratio.', rows: [['Pattern', 'Common difference (d)', 'Common ratio (r)'], ['nth term', 'a + (n-1)d', 'ar^(n-1)'], ['Sum of n terms', 'n/2[2a+(n-1)d]', 'a(r^n-1)/(r-1)'], ['Example', '2, 5, 8, 11 (d=3)', '2, 6, 18, 54 (r=3)'], ['Mean', 'Arithmetic mean: (a+b)/2', 'Geometric mean: √(ab)'], ['Growth', 'Linear growth', 'Exponential growth']], keyPoints: ['AM ≥ GM for positive numbers (AM-GM inequality)', 'Infinite GP sum = a/(1-r) when |r| < 1', 'If a, b, c are in AP: 2b = a + c', 'If a, b, c are in GP: b² = ac'], faqs: [{ q: 'What is the relationship between AP and GP?', a: 'If terms of a GP are taken as logarithms, they form an AP. Also, AM ≥ GM ≥ HM for positive real numbers.' }], relatedSlugs: ['jee-math-algebra'] },

  // More physics concepts
  { slug: 'difference-between-reflection-and-refraction', term1: 'Reflection', term2: 'Refraction', exam: 'Both', subject: 'Physics', chapter: 'Optics', intro: 'Reflection and refraction are two fundamental behaviors of light at boundaries between media. Reflection bounces light back, while refraction bends light as it passes through.', rows: [['Definition', 'Bouncing back of light from a surface', 'Bending of light when entering a different medium'], ['Medium', 'Light stays in same medium', 'Light enters a different medium'], ['Angle law', 'Angle of incidence = Angle of reflection', 'n₁sinθ₁ = n₂sinθ₂ (Snell\'s law)'], ['Speed', 'Speed unchanged', 'Speed changes with medium'], ['Wavelength', 'Unchanged', 'Changes with medium'], ['Example', 'Mirror', 'Lens, prism, diamond sparkle']], keyPoints: ['Total Internal Reflection occurs when light goes from denser to rarer medium at angle > critical angle', 'Mirrors use reflection; lenses use refraction', 'Refraction explains why a stick appears bent in water', 'Optical fibers work on Total Internal Reflection'], faqs: [{ q: 'Does frequency change during refraction?', a: 'No, frequency remains constant during refraction. Only speed and wavelength change.' }], relatedSlugs: ['jee-physics-optics'] },

  { slug: 'difference-between-conductor-and-insulator', term1: 'Conductor', term2: 'Insulator', exam: 'Both', subject: 'Physics', chapter: 'Current Electricity', intro: 'Conductors allow easy flow of electric current, while insulators resist current flow. This distinction is based on the availability of free electrons.', rows: [['Definition', 'Allows current flow', 'Resists current flow'], ['Free electrons', 'Many free electrons', 'Very few free electrons'], ['Resistivity', 'Low (10⁻⁸ to 10⁻⁶ Ω·m)', 'High (10⁸ to 10¹⁶ Ω·m)'], ['Band gap', 'No band gap (overlapping bands)', 'Large band gap (>3 eV)'], ['Temperature effect', 'Resistance increases with temperature', 'Resistance decreases with temperature'], ['Examples', 'Copper, Silver, Gold, Aluminum', 'Rubber, Glass, Wood, Plastic']], keyPoints: ['Semiconductors have intermediate conductivity (band gap ~1 eV)', 'Superconductors have zero resistance below critical temperature', 'Conductors follow Ohm\'s law: V = IR', 'Electrostatic shielding uses conductors (Faraday cage)'], faqs: [{ q: 'Why does conductor resistance increase with temperature?', a: 'Higher temperature increases lattice vibrations, causing more collisions with free electrons, thus increasing resistance.' }], relatedSlugs: ['difference-between-ac-and-dc', 'jee-physics-electrodynamics'] },

  // More bio
  { slug: 'difference-between-prokaryotic-and-eukaryotic-cell', term1: 'Prokaryotic Cell', term2: 'Eukaryotic Cell', exam: 'NEET', subject: 'Biology', chapter: 'Cell Structure', intro: 'Prokaryotic and eukaryotic cells are the two fundamental cell types. Prokaryotes lack a membrane-bound nucleus, while eukaryotes have a well-defined nucleus and organelles.', rows: [['Nucleus', 'No true nucleus (nucleoid)', 'Membrane-bound nucleus'], ['Size', 'Small (1-10 μm)', 'Large (10-100 μm)'], ['Organelles', 'No membrane-bound organelles', 'Mitochondria, ER, Golgi, etc.'], ['DNA', 'Circular, no histones', 'Linear, with histones'], ['Ribosomes', '70S', '80S'], ['Cell wall', 'Present (peptidoglycan)', 'Present in plants (cellulose), absent in animals'], ['Reproduction', 'Binary fission', 'Mitosis and meiosis'], ['Examples', 'Bacteria, Archaea', 'Plants, Animals, Fungi, Protists']], keyPoints: ['Prokaryotes evolved first (~3.5 billion years ago)', 'Endosymbiotic theory: mitochondria and chloroplasts were once prokaryotes', 'Prokaryotes can have plasmids (extra-chromosomal DNA)', 'Both types have plasma membranes, ribosomes, and DNA'], faqs: [{ q: 'Are viruses prokaryotic or eukaryotic?', a: 'Neither. Viruses are not cells — they are acellular entities with nucleic acid (DNA or RNA) enclosed in a protein coat.' }], relatedSlugs: ['difference-between-plant-and-animal-cell', 'neet-biology-coaching'] },

  { slug: 'difference-between-plant-and-animal-cell', term1: 'Plant Cell', term2: 'Animal Cell', exam: 'NEET', subject: 'Biology', chapter: 'Cell Structure', intro: 'Plant and animal cells are both eukaryotic but have key structural differences. Plant cells have cell walls and chloroplasts, while animal cells have centrioles and are more flexible.', rows: [['Cell wall', 'Present (cellulose)', 'Absent'], ['Chloroplasts', 'Present', 'Absent'], ['Vacuole', 'Large central vacuole', 'Small or absent'], ['Shape', 'Fixed rectangular shape', 'Irregular/flexible shape'], ['Centrioles', 'Absent (usually)', 'Present'], ['Lysosomes', 'Rare', 'Prominent'], ['Storage', 'Starch', 'Glycogen'], ['Plasmodesmata', 'Present', 'Absent (gap junctions instead)']], keyPoints: ['Both have nucleus, mitochondria, ER, Golgi apparatus, ribosomes', 'Plant cells can perform photosynthesis (have chloroplasts)', 'Animal cells have more prominent lysosomes ("suicide bags")', 'Cell wall provides rigidity and protection to plant cells'], faqs: [{ q: 'Do plant cells have mitochondria?', a: 'Yes. Plant cells have both chloroplasts (for photosynthesis) and mitochondria (for cellular respiration). They perform respiration 24/7 and photosynthesis only in light.' }], relatedSlugs: ['difference-between-prokaryotic-and-eukaryotic-cell'] },

  { slug: 'difference-between-enzyme-and-hormone', term1: 'Enzyme', term2: 'Hormone', exam: 'NEET', subject: 'Biology', intro: 'Enzymes and hormones are both biological molecules that regulate body functions, but they work very differently. Enzymes are biological catalysts, while hormones are chemical messengers.', rows: [['Nature', 'Mostly proteins', 'Proteins, steroids, or amines'], ['Function', 'Catalyze biochemical reactions', 'Chemical messengers'], ['Action site', 'At the site of production', 'At target organs (distant)'], ['Consumed?', 'Not consumed (reusable)', 'Used up after action'], ['Speed', 'Very fast catalysis', 'Slower, longer-lasting effects'], ['Molecular weight', 'High', 'Variable (can be small)'], ['Example', 'Amylase, Pepsin, Lipase', 'Insulin, Adrenaline, Thyroxine']], keyPoints: ['Enzymes are highly specific (lock-and-key / induced fit model)', 'Hormones travel through blood to reach target organs', 'Enzyme activity depends on pH, temperature, and substrate concentration', 'Hormones regulate growth, metabolism, reproduction, and homeostasis'], faqs: [{ q: 'Can a substance be both an enzyme and a hormone?', a: 'No, but they can work together. For example, insulin (hormone) regulates glucose levels, while hexokinase (enzyme) catalyzes glucose phosphorylation.' }], relatedSlugs: ['neet-biology-coaching'] },
];

